/* ===== module: instruction-loader.js ===== */
    /** Loads catalog instruction text on demand (DB split, 2026-10-28).
        The bundled database (data/exercises-db.js) carries every record
        WITHOUT its steps — the text lives in data/exercise-instructions-N.js
        shards, one per id range; window.FREE_EXERCISE_INSTRUCTION_SHARDS
        (data/exercise-instruction-shards.js, generated by
        infra/split-exercise-instructions.js) names each shard's first id. ensureExerciseInstructions(id)
        fetches the id's shard once, assigns its steps onto the catalog
        entries, and resolves them; the service worker's cache-first fetch
        handler keeps a fetched shard in the app cache, so later opens —
        including offline ones — render synchronously from the entry. A
        failed fetch (offline before the first visit) resolves null so the
        caller degrades gracefully instead of breaking the page. Custom
        exercises and the 24-exercise fallback catalog carry their steps
        inline and never touch this loader. Shards are deliberately NOT in
        the SW precache list: they download on first use, not at install. */
    window.FREE_EXERCISE_INSTRUCTIONS = window.FREE_EXERCISE_INSTRUCTIONS || {};
    const _instructionShardLoads = new Map();
    const _instructionAppliedIds = new Set();
    /* The shard holding an id: the last shard whose first id sorts at or
       before it (ids and boundaries share code-unit order). */
    function exerciseInstructionShardIndex(id){
      const bounds = Array.isArray(window.FREE_EXERCISE_INSTRUCTION_SHARDS) ? window.FREE_EXERCISE_INSTRUCTION_SHARDS : [];
      let idx = 0;
      for (let i = 0; i < bounds.length; i++) if (bounds[i] <= id) idx = i;
      return idx;
    }
    /* Assigns every loaded shard's steps onto its catalog entry.
       Idempotent: an id is applied once. */
    function applyLoadedExerciseInstructions(){
      const map = window.FREE_EXERCISE_INSTRUCTIONS || {};
      for (const id of Object.keys(map)) {
        if (_instructionAppliedIds.has(id)) continue;
        _instructionAppliedIds.add(id);
        const entry = typeof catalogEntryById === 'function' ? catalogEntryById(id) : undefined;
        if (entry) entry.instructions = map[id];
      }
    }
    /* Fetches one shard exactly once; resolves true when its steps are
       applied, false when the fetch failed. */
    function loadExerciseInstructionShard(index){
      if (_instructionShardLoads.has(index)) return _instructionShardLoads.get(index);
      const promise = new Promise((resolve) => {
        if (typeof document === 'undefined' || !document.createElement || !(document.head || document.documentElement)) { resolve(false); return; }
        const script = document.createElement('script');
        script.src = `data/exercise-instructions-${index}.js`;
        script.onload = () => { applyLoadedExerciseInstructions(); resolve(true); };
        script.onerror = () => resolve(false);
        (document.head || document.documentElement).appendChild(script);
      });
      _instructionShardLoads.set(index, promise);
      return promise;
    }
    /* Resolves an exercise's steps: the array when known (already on the
       entry, or loaded by this call), [] when the shard loaded but holds
       no steps for the id, null when the shard could not be fetched. */
    function ensureExerciseInstructions(id){
      const entry = typeof catalogEntryById === 'function' ? catalogEntryById(id) : undefined;
      if (entry && entry.instructions && entry.instructions.length) return Promise.resolve(entry.instructions);
      if (!Array.isArray(window.FREE_EXERCISE_INSTRUCTION_SHARDS) || !window.FREE_EXERCISE_INSTRUCTION_SHARDS.length) return Promise.resolve(null);
      return loadExerciseInstructionShard(exerciseInstructionShardIndex(id)).then((ok) => {
        const fresh = typeof catalogEntryById === 'function' ? catalogEntryById(id) : undefined;
        if (fresh && fresh.instructions && fresh.instructions.length) return fresh.instructions;
        return ok ? [] : null;
      });
    }
